#include <stdio.h>#include <stdlib.h>#include <string.h>#include "mesh.h"#include "FileStuff.h"#include "BMP.h"OSErr putPassability ( FSSpec &theMeshFSSpec );OSErr putPassability ( FSSpec &theMeshFSSpec ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef;	OSErr		theError;	unsigned char *theMap;	int		colorCounter[256];	int			i, j, k, l, x, y;	char		maxColor;	long		theWidth, theHeight, theSize;	long		thePictureWidth, thePictureHeight, thePictureSize;	meshHeader	theMeshHeader;	gridData	*theGrid;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	theWidth = theMeshHeader.meshWidth * 16;	theHeight = theMeshHeader.meshHeight * 16;	theSize =  theWidth * theHeight;	thePictureWidth = theWidth * 16;	thePictureHeight = theHeight * 16;	thePictureSize = thePictureWidth * thePictureHeight;	theGrid = (struct gridData *) NewPtr (theSize * sizeof(gridData));	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	FileRead(theGrid, theMeshHeader.meshLength, theMeshFileRef);	theMap = (unsigned char *) NewPtr ( thePictureSize );	if ( theMap == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theError = readBMP ( "\p:Graphics.in:passability.bmp", thePictureWidth, thePictureHeight, nil, (char *) theMap );	if ( theError != noErr ){		DisposePtr ( (Ptr) theMap );		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return theError;	}	for ( y = 0, i = 0; y < thePictureHeight - 1; y += 32, i += theWidth ){		for ( x = thePictureWidth - 32; x >= 0; x -= 32, i += 2 ){			for ( k = 0; k < 16; k++ ){				for (l = 0; l < 16; l++ )		// clear the counter					colorCounter[l] = 0;				for ( j = 0; j < 16 - k; j++ )					colorCounter[ theMap[x + y * thePictureWidth + j + k * thePictureWidth] ]++;		// find most freq. color				maxColor = 0;				for (l = 0; l < 16; l++ )					if ( colorCounter[l] > maxColor )						maxColor = l;				theGrid[i + 1].passability = maxColor;								for (l = 0; l < 16; l++ )					colorCounter[l] = 0;				for ( j = 15; j > 15 - k; j-- )					colorCounter[ theMap[x + y * thePictureWidth + j + k * thePictureWidth] ]++;				maxColor = 0;				for (l = 0; l < 16; l++ )					if ( colorCounter[l] > maxColor )						maxColor = l;				theGrid[i + 1].passability |= maxColor << 4;				for (l = 0; l < 16; l++ )					colorCounter[l] = 0;				for ( j = k; j < 16; j++ )					colorCounter[ theMap[x + 16 + y * thePictureWidth + j + k * thePictureWidth] ]++;				maxColor = 0;				for (l = 0; l < 16; l++ )					if ( colorCounter[l] > maxColor )						maxColor = l;				theGrid[i].passability = maxColor << 4;				for (l = 0; l < 16; l++ )					colorCounter[l] = 0;				for ( j = 0; j < k; j++ )					colorCounter[ theMap[x + 16 + y * thePictureWidth + j + k * thePictureWidth] ]++;				maxColor = 0;				for (l = 0; l < 16; l++ )					if ( colorCounter[l] > maxColor )						maxColor = l;				theGrid[i].passability |= maxColor;				for (l = 0; l < 16; l++ )					colorCounter[l] = 0;				for ( j = k; j < 16; j++ )					colorCounter[ theMap[x + (y + 16) * thePictureWidth + j + k * thePictureWidth] ]++;				maxColor = 0;				for (l = 0; l < 16; l++ )					if ( colorCounter[l] > maxColor )						maxColor = l;				theGrid[i + theWidth + 1].passability = maxColor << 4;				for (l = 0; l < 16; l++ )					colorCounter[l] = 0;				for ( j = 0; j < k; j++ )					colorCounter[ theMap[x + (y + 16) * thePictureWidth + j + k * thePictureWidth] ]++;				maxColor = 0;				for (l = 0; l < 16; l++ )					if ( colorCounter[l] > maxColor )						maxColor = l;				theGrid[i + theWidth + 1].passability |= maxColor;				for (l = 0; l < 16; l++ )					colorCounter[l] = 0;				for ( j = 0; j < 16 - k; j++ )					colorCounter[ theMap[x + 16 + (y + 16) * thePictureWidth + j + k * thePictureWidth] ]++;				maxColor = 0;				for (l = 0; l < 16; l++ )					if ( colorCounter[l] > maxColor )						maxColor = l;					theGrid[i + theWidth].passability = maxColor;				for (l = 0; l < 16; l++ )					colorCounter[l] = 0;				for ( j = 15; j > 15 - k; j-- )					colorCounter[ theMap[x + 16 + (y + 16) * thePictureWidth + j + k * thePictureWidth] ]++;				maxColor = 0;				for (l = 0; l < 16; l++ )					if ( colorCounter[l] > maxColor )						maxColor = l;					theGrid[i + theWidth].passability |= maxColor << 4;			}		}	}	FileSeek ( theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, theMeshFileRef);	DisposePtr ( (Ptr) theMap );	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );	return	noErr;}